function details(id){const i=data.items.find(x=>x.id===id);if(!i)return;const ep=i.episodes.find(e=>e.id===i.lastEpisode)||i.episodes[0];formDialog('影片档案',`<label>片名<input id="detail-title" required value="${esc(i.title)}"></label><div class="two-col"><label>状态<select id="detail-status">${[['want','想看'],['watching','观看中'],['done','已看']].map(([v,t])=>`<option value="${v}" ${i.status===v?'selected':''}>${t}</option>`).join('')}</select></label><label>我的评分<select id="detail-rating">${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${i.rating===n?'selected':''}>${n?'★'.repeat(n):'暂不评分'}</option>`).join('')}</select></label></div><label>影片类型<select id="detail-kind"><option value="movie" ${i.kind==='movie'?'selected':''}>电影</option><option value="series" ${i.kind==='series'?'selected':''}>电视剧</option></select></label><label>分类 / 标签<input id="detail-category" value="${esc(i.category)}" placeholder="例如：人生、艺术、纪录片"></label><label>观后感<textarea id="detail-review" placeholder="这个故事给你留下了什么？">${esc(i.review)}</textarea></label><div class="row wrap"><button type="button" id="poster">更换封面</button><button type="button" id="relink">重新关联文件</button><button type="button" id="remove-item" class="danger">移出片库</button></div><p class="details-path">${ep.mediaFile?'✓ 已保存并校验 · 本机影库副本':'此资源尚未保存为影库副本'}<br>${esc(ep.path)}${i.kind==='series'?'<br>可在播放页的「选集」中重新关联指定一集。':''}</p>`,async()=>{await api.updateItem(id,{title:$('#detail-title').value,kind:$('#detail-kind').value,status:$('#detail-status').value,rating:Number($('#detail-rating').value),category:$('#detail-category').value,review:$('#detail-review').value});closeDialog();await refresh();render()});on('#poster',async()=>{await api.poster(id);await refresh();toast('封面已更新')});on('#relink',async()=>{await api.relink(id,ep.id);await refresh();toast('视频文件已重新关联')});on('#remove-item',()=>removeMovieDialog(id));}
function renderSources(){$('.main').innerHTML=`<div class="top"><div><div class="eyebrow">DISCOVER YOUR NEXT STORY</div><h1>影视资源</h1><small>常用的网站，由你自己收藏与整理。</small></div><button class="primary" id="add-source">＋ 添加网站</button></div><div class="source-grid">${data.sources.map(s=>`<article class="source"><span class="tag">${esc(s.tag)}</span><h2>${esc(s.name)} ↗</h2><p>${esc(s.description)}</p><span class="source-url">${esc(s.url)}</span><div class="row"><button data-open-source="${s.id}">前往网站 ↗</button><span class="grow"></span><button class="ghost small" data-edit-source="${s.id}">编辑</button><button class="ghost small danger" data-delete-source="${s.id}">删除</button></div></article>`).join('')}</div><p class="muted" style="font-size:12px;margin-top:25px">网站在系统浏览器打开。名称、网址和说明均可修改，并随观影日记备份。</p>`;on('#add-source',()=>sourceDialog());$$('[data-open-source]').forEach(b=>b.onclick=()=>safe(()=>api.openSource(b.dataset.openSource)));$$('[data-edit-source]').forEach(b=>b.onclick=()=>sourceDialog(b.dataset.editSource));$$('[data-delete-source]').forEach(b=>b.onclick=()=>confirmDialog('移除网站','从资源列表移除这个入口？',async()=>{await api.deleteSource(b.dataset.deleteSource);await refresh();renderSources()}));}
function sourceDialog(id){const s=data.sources.find(x=>x.id===id)||{};formDialog(id?'编辑网站':'添加网站',`<label>网站名称<input id="source-name" required maxlength="100" value="${esc(s.name)}"></label><label>网址<input id="source-url" required value="${esc(s.url)}" placeholder="https://"></label><label>分类<input id="source-tag" value="${esc(s.tag)}"></label><label>说明<textarea id="source-desc">${esc(s.description)}</textarea></label>`,async()=>{await api.saveSource({id,name:$('#source-name').value,url:$('#source-url').value,tag:$('#source-tag').value,description:$('#source-desc').value});closeDialog();await refresh();renderSources()});}
function noteCard(n,compact=false){const i=data.items.find(x=>x.id===n.itemId);return `<article tabindex="0" data-note-id="${n.id}" class="note-card ${esc(n.color)}">${batchCheckbox('notes',n.id,'选择摘记 '+(n.text||i?.title||'画面'))}${n.shots[0]?`<img src="${imageUrl(n.shots[0].image)}" alt="收藏的电影画面" data-preview="${n.id}">`:''}<div class="note-body"><div class="row between"><small>${compact?'':esc(i?.title)+' · '}${n.kind==='quote'?'台词片段':n.kind==='frame'?'画面收藏':'截图'}</small><span class="note-time">${stamp(n.start)}${n.end>n.start?' — '+stamp(n.end):''}</span></div>${n.text?`<blockquote>${esc(n.text)}</blockquote>`:''}${n.comment?`<p>${esc(n.comment)}</p>`:''}${n.tags?`<span class="tags">${esc(n.tags)}</span>`:''}<div class="note-actions"><button data-revisit="${n.id}">${n.kind==='quote'?'▶ 回看片段':'◉ 回到这一帧'}</button>${n.kind==='quote'?`<button data-loop="${n.id}">循环</button>`:''}${n.shots.length?`<button data-collage="${n.id}">${n.shots.length>1?'导出拼图':'导出图片'}</button>`:''}<button data-edit-note="${n.id}">编辑</button><button class="ghost danger" data-delete-note="${n.id}">删除</button></div></div></article>`;}
function bindNotes(){const container=$('#all-notes')?'#all-notes':$('#panel-notes')?'#panel-notes':null;if(container)mountBatch('notes',container,$$(container+' [data-note-id]').map(n=>n.dataset.noteId));for(const b of $$('[data-revisit]'))b.onclick=()=>safe(()=>revisit(b.dataset.revisit));for(const b of $$('[data-loop]'))b.onclick=()=>safe(()=>revisit(b.dataset.loop,true));for(const b of $$('[data-collage]'))b.onclick=()=>collage(data.notes.find(n=>n.id===b.dataset.collage));for(const b of $$('[data-preview]'))b.onclick=()=>collage(data.notes.find(n=>n.id===b.dataset.preview));for(const b of $$('[data-edit-note]'))b.onclick=()=>noteDialog(data.notes.find(n=>n.id===b.dataset.editNote));for(const b of $$('[data-delete-note]'))b.onclick=()=>confirmDialog('删除摘记','删除这条摘记？其他摘记和原视频会保留。',async()=>{await api.deleteNote(b.dataset.deleteNote);await refresh();if(view==='player'){renderPanel();renderMarks()}else renderNotesPage()} );}
function renderNotesPage(){$('.main').innerHTML=`<div class="top"><div><div class="eyebrow">MOMENTS WORTH KEEPING</div><h1>我的摘记</h1><small>一句话，一帧光，一次被触动的瞬间。</small></div><button id="export-all">导出图文笔记</button></div><div class="toolbar"><div class="chips">${[['all','全部'],['quote','台词'],['frame','画面'],['shot','截图']].map(([id,t])=>`<button class="chip ${filter===id?'active':''}" data-nfilter="${id}">${t}</button>`).join('')}</div><input id="note-search" class="search" value="${esc(search)}" placeholder="搜索台词、感想、标签、片名"></div><div id="all-notes"></div>`;const draw=()=>{const notes=data.notes.filter(n=>(filter==='all'||n.kind===filter)&&[n.text,n.comment,n.tags,data.items.find(i=>i.id===n.itemId)?.title].join(' ').toLowerCase().includes(search.toLowerCase()));$('#all-notes').innerHTML=notes.length?`<div class="notes-grid">${notes.map(n=>noteCard(n)).join('')}</div>`:'<div class="empty"><div class="empty-icon">◇</div><h2>把触动你的瞬间留在这里</h2><p>播放时收藏台词、截图或标记画面，就会出现在这里。</p></div>';bindNotes();};draw();$('#note-search').oninput=e=>{search=e.target.value;draw()};$$('[data-nfilter]').forEach(b=>b.onclick=()=>{filter=b.dataset.nfilter;renderNotesPage()});on('#export-all',async()=>{if(await api.exportMarkdown())toast('图文笔记已导出')});}
function renderDiary(){const entries=data.items.flatMap(i=>(i.sessions||[]).map(s=>({i,s}))).sort((a,b)=>b.s.date.localeCompare(a.s.date));let last='';$('.main').innerHTML=`<div class="top"><div><div class="eyebrow">STORIES BECOME PART OF YOU</div><h1>观影日记</h1><small>记录每次认真观看，也留一处安放感想。</small></div></div>${entries.length?entries.map(({i,s})=>{const date=new Date(s.date).toLocaleDateString('zh-CN',{year:'numeric',month:'long',day:'numeric'}),head=date!==last?`<div class="diary-day">${date}</div>`:'';last=date;return head+`<article class="diary-entry">${batchCheckbox('films',i.id,'选择影片 '+i.title)}<div class="row between"><div><h3>${esc(i.title)} ${i.rating?' · '+'★'.repeat(i.rating):''}</h3><small>${esc(i.episodes.find(e=>e.id===s.episodeId)?.title)} · ${new Date(s.date).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})}</small></div><button class="small" data-diary-edit="${i.id}">写观后感</button></div>${i.review?`<p style="white-space:pre-wrap;margin:15px 0 0">${esc(i.review)}</p>`:''}</article>`}).join(''):'<div class="empty"><div class="empty-icon">▦</div><h2>故事从下一次播放开始</h2><p>观看十秒后自动留下日期记录。<br>评分和感想可在影片档案中填写。</p></div>'}`;$$('[data-diary-edit]').forEach(b=>b.onclick=()=>details(b.dataset.diaryEdit));const list=document.createElement('div');list.id='diary-list';const main=$('.main');while(main.children.length>1)list.append(main.children[1]);main.append(list);mountBatch('films','#diary-list',entries.map(e=>e.i.id));}
function renderSettings(){$('.main').innerHTML=`<div class="eyebrow">QUIETLY YOURS</div><h1>偏好与备份</h1><div class="settings-card"><h2>让记录好好留下</h2><p>影片进度、台词、画面、观后感和资源网站保存在本机。备份包含笔记、截图和字幕；此处备份不含视频，视频副本独立保存在影库存储位置。换机时还需迁移视频；账号同步状态请查看「账号与 B 站」。</p><div class="row wrap"><button class="primary" id="backup">备份全部日记</button><button id="restore">从备份恢复</button><button id="open-data">打开数据文件夹</button></div></div><div class="settings-card"><h2>资源保存位置</h2><p>新导入的资源会复制到下面的位置，保存并校验成功后，播放不再依赖原下载文件。</p><p class="details-path">${esc(data.storage?.folder)}</p><p>已保存 ${data.storage?.storedCount||0} 个视频 · ${formatBytes(data.storage?.storedBytes||0)}<br>可用空间 ${formatBytes(data.storage?.freeBytes)}</p><div class="row wrap"><button id="storage-open">打开影库文件夹</button><button id="storage-change">更换新资源保存位置</button>${data.storage?.legacyCount?'<button id="storage-migrate">保存旧版引用资源</button>':''}</div><small>更换位置只影响以后导入的资源，已有视频仍可从原影库位置播放。卸载或更新程序时请保留影库文件夹。</small></div><div class="settings-card"><h2>跨设备使用</h2><p>通过「账号与 B 站」连接服务，同步影片档案、进度、笔记和截图。仅本机服务不支持换机；视频文件不在本次同步范围。iPad 功能暂缓。</p></div><div class="settings-card"><h2>观看习惯</h2><label class="row"><input type="checkbox" id="auto-next" ${data.settings.autoNext?'checked':''}> 剧集播完后自动播放下一集</label><p style="margin-top:18px;margin-bottom:0">原画播放，不转码。速度提供 1×、1.25×、1.5×、2×；可切换音轨、字幕和调整字幕延迟。</p></div><div class="settings-card"><h2>几枚顺手的快捷键</h2><p><kbd>空格</kbd> 暂停 / 播放　<kbd>← →</kbd> 后退 / 前进 5 秒</p><p><kbd>I</kbd> 标记片段开始　<kbd>O</kbd> 标记结束并写笔记</p><p><kbd>N</kbd> 收藏当前台词　<kbd>S</kbd> 截图　<kbd>B</kbd> 收藏这一帧</p><p><kbd>,</kbd> 上一帧　<kbd>.</kbd> 下一帧　<kbd>F</kbd> 全屏　<kbd>M</kbd> 静音</p><small>输入笔记时快捷键自动停用。截图保存原视频像素尺寸；显示器能力会影响 HDR 呈现。</small></div>`;on('#backup',async()=>{if(await api.backup())toast('日记、截图和字幕已备份')});on('#restore',async()=>{if(await api.restore()){await refresh();render();toast('备份已恢复，恢复前的数据也已留存')}});on('#open-data',()=>api.openData());on('#storage-open',()=>api.openStorage());on('#storage-change',async()=>{if(await api.chooseStorage()){await refresh();renderSettings()}});on('#storage-migrate',preserveExisting);$('#auto-next').onchange=e=>safe(async()=>{await api.saveSettings({autoNext:e.target.checked});await refresh()});}
async function openMovie(id,epId,start,end,loop=false){current=data.items.find(i=>i.id===id);if(!current)throw Error('影片已不在片库');episode=current.episodes.find(e=>e.id===epId)||current.episodes.find(e=>e.id===current.lastEpisode)||current.episodes[0];if(current.source==='bilibili'){await api.openWebNote(id,episode.id,start??episode.position??0,end,loop);toast('已在浏览器打开 B 站；安装并启用插件后可回看片段');return;}if(!episode.path){toast('已同步影片档案和摘记，视频仍在原电脑。请在影片档案重新关联文件');current=null;episode=null;return;}view='player';selectedCues.clear();markStart=null;state={};renderPlayer();try{const r=await api.play(current.id,episode.id,start,end,loop);current=r.item;episode=current.episodes.find(e=>e.id===r.episode.id);renderPanel();scheduleBounds();}catch(e){toast(e.message);$('#video-message').innerHTML='无法播放<br>请检查原文件，或在影片档案中重新关联。';}}
async function revisit(id,loop=false){const n=data.notes.find(n=>n.id===id);reviewStart=n.start;await openMovie(n.itemId,n.episodeId,n.start,n.kind==='quote'?n.end:undefined,loop);if(data.items.find(i=>i.id===n.itemId)?.source==='bilibili')return;if(n.kind!=='quote'&&view==='player')await api.control('pause',true);}
function renderPlayer(){resizeObserver?.disconnect();$('#app').innerHTML=`<div class="player-shell ${focusMode?'focus-mode':''}"><header class="player-top"><button class="ghost" id="back">← 片库</button><div class="grow"><div class="player-title">${esc(current.title)}</div><div class="player-subtitle">${current.kind==='series'?esc(episode.title)+' · ':''}<span id="quality">原画播放</span></div></div><button class="ghost small" id="movie-info">影片档案</button><button class="ghost small" id="focus">${focusMode?'退出专注':'专注观看'}</button><button class="ghost small" id="toggle-controls">操作栏 C</button><button class="ghost small" id="toggle-panel">摘记面板 P</button><button class="ghost small" id="shortcut-help">快捷键 F1</button></header><div class="review-strip" id="review-strip" hidden><span id="review-label"></span><button id="review-exit">返回正常播放</button></div><div class="player-work"><section class="cinema-stage"><div class="video-area" id="video-area"><div class="video-placeholder" id="video-message"><strong>影</strong>正在打开原视频…</div></div><div class="controls"><div class="mark-strip" id="mark-strip" hidden></div><div class="timeline"><div class="timeline-marks" id="marks"></div><input type="range" id="seek" min="0" max="1" value="0" step="0.01" aria-label="播放进度"></div><div class="play-row"><button id="play-toggle" aria-label="播放暂停">Ⅱ</button><button id="back5" title="后退5秒">−5s</button><button id="forward5" title="前进5秒">+5s</button><span class="time" id="time">00:00:00 / 00:00:00</span><span class="grow"></span><button id="mute" title="静音">♪</button><input class="volume" id="volume" type="range" min="0" max="100" value="70" aria-label="音量"><select id="speed" aria-label="播放速度"><option value="1">1×</option><option value="1.25">1.25×</option><option value="1.5">1.5×</option><option value="2">2×</option></select><button id="tracks" title="音轨和字幕">字幕 / 音轨</button><button id="fullscreen" title="全屏 F">⛶</button></div></div><div class="toolbelt"><button id="mark-start">［ 起点 I</button><button id="mark-end">终点 O ］</button><button id="quote" class="primary">摘一句 N</button><button id="shot">▣ 截图 S</button><button id="frame">◇ 收藏画面 B</button><button id="prev-frame" title="上一帧 ,">‹ 帧</button><button id="next-frame" title="下一帧 .">帧 ›</button><span class="hint">留住打动你的瞬间</span></div></section><aside class="note-panel"><div class="panel-tabs">${[['notes','摘记'],['subtitles','台词'],['episodes','选集']].map(([id,t])=>`<button data-panel="${id}" class="${panel===id?'active':''}">${t}</button>`).join('')}</div><div class="panel-content"></div></aside></div></div>`;on('#back',async()=>{await api.stop();current=null;episode=null;view='library';await refresh();render()});on('#movie-info',()=>details(current.id));on('#play-toggle',()=>api.control('toggle'));on('#back5',()=>api.control('relative',-5));on('#forward5',()=>api.control('relative',5));on('#mute',()=>api.control('mute'));on('#fullscreen',()=>api.fullscreen());on('#focus',()=>keyAction('immersive'));on('#toggle-controls',()=>keyAction('controls'));on('#toggle-panel',()=>keyAction('panel'));on('#shortcut-help',shortcutHelp);on('#tracks',tracksDialog);on('#mark-start',()=>keyAction('start'));on('#mark-end',()=>keyAction('end'));on('#quote',()=>keyAction('quote'));on('#shot',()=>keyAction('shot'));on('#frame',()=>keyAction('frame'));on('#prev-frame',()=>api.control('previousFrame'));on('#next-frame',()=>api.control('nextFrame'));on('#review-exit',()=>api.control('clearReview'));$('#seek').onchange=e=>safe(()=>api.control('seek',Number(e.target.value)));$('#seek').oninput=e=>$('#time').textContent=stamp(e.target.value)+' / '+stamp(state.duration);$('#volume').oninput=e=>safe(()=>api.control('volume',Number(e.target.value)));$('#speed').onchange=e=>safe(()=>api.control('speed',Number(e.target.value)));$$('[data-panel]').forEach(b=>b.onclick=()=>{panel=b.dataset.panel;$$('[data-panel]').forEach(x=>x.classList.toggle('active',x===b));renderPanel()});on('#video-area',()=>{});$('#video-area').ondblclick=e=>{e.preventDefault();safe(()=>api.videoDoubleClick())};renderPanel();applyPlayerLayout();resizeObserver=new ResizeObserver(scheduleBounds);resizeObserver.observe($('#video-area'));scheduleBounds();}
let boundsQueued=false;function scheduleBounds(){if(boundsQueued)return;boundsQueued=true;requestAnimationFrame(()=>{boundsQueued=false;const el=$('#video-area');if(el){const r=el.getBoundingClientRect();api.bounds({x:r.x,y:r.y,width:r.width,height:r.height});}})}
function renderMarks(){if(!$('#marks'))return;const dur=state.duration||episode?.duration||1;$('#marks').innerHTML=data.notes.filter(n=>n.episodeId===episode?.id).map(n=>`<i class="timeline-mark" style="left:${Math.min(100,n.start/dur*100)}%;width:${Math.max(.25,(n.end-n.start)/dur*100)}%"></i>`).join('');}
function renderPanel(){const box=$('.panel-content');if(!box||!current)return;if(panel==='notes'){const notes=data.notes.filter(n=>n.itemId===current.id);box.innerHTML=`<div class="row between" style="margin-bottom:12px"><span class="panel-header" style="margin:0">${notes.length} 条摘记 · 可点击回看</span><button id="export-current" class="ghost small">导出</button></div><input class="search" id="panel-search" placeholder="搜索台词和笔记"><div id="panel-notes">${notes.length?notes.map(n=>noteCard(n,true)).join(''):'<p class="panel-header">看到喜欢的台词？<br>按 N 摘一句，或用 I / O 标记一段。<br><br>按 S 截图，按 B 收藏画面。<br>截图和画面都可添加感想。</p>'}</div>`;bindNotes();on('#export-current',async()=>{if(await api.exportMarkdown(current.id))toast('影片摘记已导出')});$('#panel-search').oninput=e=>{const q=e.target.value.toLowerCase();$('#panel-notes').innerHTML=notes.filter(n=>[n.text,n.comment,n.tags].join(' ').toLowerCase().includes(q)).map(n=>noteCard(n,true)).join('');bindNotes()};}else if(panel==='episodes'){box.innerHTML=`<div class="panel-header">${current.kind==='series'?'按季、集数排序。点击一集继续观看。':'当前影片'}</div>${current.episodes.map((e,i)=>`<div class="episode ${e.id===episode.id?'active':''}" data-episode="${e.id}">${batchCheckbox('episodes',e.id,'选择集数 '+e.title)}<span class="ep-no">${String(e.episode||i+1).padStart(2,'0')}</span><div class="grow"><div class="episode-title">${esc(e.title)}</div><small>${e.completed?'已看完':e.position?'看到 '+stamp(e.position):'未开始'}${e.season>1?' · 第'+e.season+'季':''}</small></div></div>`).join('')}<button class="small" id="relink-current">重新关联当前视频</button>`;const epList=document.createElement('div');epList.id='episode-list';while(box.firstChild)epList.append(box.firstChild);box.append(epList);mountBatch('episodes','#episode-list',current.episodes.map(e=>e.id));$$('[data-episode]').forEach(b=>b.onclick=e=>{if(!e.target.closest('label,input'))safe(()=>openMovie(current.id,b.dataset.episode))});on('#relink-current',async()=>{if(await api.relink(current.id,episode.id)){await refresh();toast('已关联，可重新打开该集')}});}else renderSubtitles();renderMarks();}
function getCues(){const delay=Number(state['sub-delay']??episode?.subDelay)||0;return (episode?.cues||[]).map(c=>({...c,start:Math.max(0,c.start+delay),end:Math.max(0,c.end+delay)}));}
function renderSubtitles(){const cues=getCues();$('.panel-content').innerHTML=`<div class="subtitle-tools"><button id="load-subs">＋ 导入字幕</button><button class="primary" id="collect-cues">摘录所选 <span id="cue-count">${selectedCues.size||''}</span></button></div><input class="search" id="sub-search" placeholder="搜索台词"><div class="panel-header">${cues.length?'勾选多句生成片段笔记；点击台词跳转播放。':'内嵌字幕可用「摘一句 N」记录当前台词。<br>导入 SRT / ASS / VTT 后可搜索与批量选择。'}</div><div id="cue-list"></div>`;const draw=q=>{$('#cue-list').innerHTML=cues.filter(c=>!q||c.text.toLowerCase().includes(q.toLowerCase())).slice(0,3000).map(c=>`<div class="subtitle-cue" data-cue-row="${c.id}"><input type="checkbox" data-cue="${c.id}" aria-label="选择 ${esc(c.text)}" ${selectedCues.has(c.id)?'checked':''}><div class="cue-text" data-cue-seek="${c.start}"><span class="cue-time">${stamp(c.start)} — ${stamp(c.end)}</span>${esc(c.text)}</div></div>`).join('');$$('[data-cue]').forEach(b=>b.onchange=()=>{if(b.checked)selectedCues.add(Number(b.dataset.cue));else selectedCues.delete(Number(b.dataset.cue));$('#cue-count').textContent=selectedCues.size||''});$$('[data-cue-seek]').forEach(b=>b.onclick=()=>safe(()=>api.control('seek',Number(b.dataset.cueSeek))));};draw();$('#sub-search').oninput=e=>draw(e.target.value);on('#load-subs',async()=>{const r=await api.loadSubtitles(current.id,episode.id);if(r){await refresh();selectedCues.clear();renderSubtitles();toast('已导入 '+r.cues.length+' 句台词')}});on('#collect-cues',async()=>{const chosen=cues.filter(c=>selectedCues.has(c.id));if(!chosen.length)return toast('先勾选想摘录的台词');if(chosen.length>20)return toast('每次最多选择 20 句');const shots=await busyWork(()=>api.captureCues(chosen),'正在按台词提取原尺寸画面…');if(shots)noteDialog({itemId:current.id,episodeId:episode.id,kind:'quote',start:chosen[0].start,end:Math.max(...chosen.map(c=>c.end)),text:chosen.map(c=>c.text).join('\n'),shots,color:'gold'});});}
async function busyWork(fn,text){const d=document.createElement('div');d.className='busy-mask';d.innerHTML=`<div>${esc(text)}<p class="muted" style="font-size:12px">完成后回到刚才的播放位置</p></div>`;document.body.append(d);await api.previewHidden(true);try{return await fn()}finally{d.remove();await api.previewHidden(false)}}
async function keyAction(action){if(view!=='player'||$('#modal').open||state.busy)return;if(action==='reveal'){if(focusMode){$('.player-shell')?.classList.add('chrome-revealed');scheduleBounds();clearTimeout(revealTimer);revealTimer=setTimeout(()=>{$('.player-shell')?.classList.remove('chrome-revealed');scheduleBounds()},2600);}return;}if(action==='immersive'){focusMode=!focusMode;controlsHidden=panelHidden=focusMode;await api.fullscreen(focusMode);applyPlayerLayout();return;}if(action==='controls'||action==='panel'){if(action==='controls')controlsHidden=!controlsHidden;else panelHidden=!panelHidden;focusMode=controlsHidden&&panelHidden;if(focusMode)await api.fullscreen(true);applyPlayerLayout();return;}if(action==='help')return shortcutHelp();if(action==='tracks')return tracksDialog();if(action==='archive')return details(current.id);if(action==='exitReview')return api.control('clearReview');if(action==='exportNotes'){if(await api.exportMarkdown(current.id))toast('摘记已导出');return;}if(action==='loadSubs'){const r=await api.loadSubtitles(current.id,episode.id);if(r){await refresh();panel='subtitles';panelHidden=false;focusMode=false;applyPlayerLayout();renderPanel();}return;}if(action==='backLibrary'){await api.stop();view='library';current=null;episode=null;focusMode=controlsHidden=panelHidden=false;await api.fullscreen(false);await refresh();render();return;}if(action==='speed'){const speeds=[1,1.25,1.5,2];return api.control('speed',speeds[(speeds.indexOf(state.speed||1)+1)%4]);}if(action==='volumeUp'||action==='volumeDown')return api.control('volume',(state.volume??70)+(action==='volumeUp'?5:-5));if(['notesPanel','subtitlesPanel','episodesPanel'].includes(action)){panel={notesPanel:'notes',subtitlesPanel:'subtitles',episodesPanel:'episodes'}[action];panelHidden=false;focusMode=false;applyPlayerLayout();$('[data-panel]').forEach(x=>x.classList.toggle('active',x.dataset.panel===panel));renderPanel();return;}if(action==='collectCues')return $('#collect-cues')?.click();if(action==='fullscreen')return api.fullscreen();if(action==='escape'){await api.fullscreen(false);focusMode=controlsHidden=panelHidden=false;applyPlayerLayout();return;}if(action==='mute')return api.control('mute');const t=Number(state['time-pos'])||0;if(action==='start'){markStart=await api.beginRange();$('#mark-strip').hidden=false;$('#mark-strip').textContent='片段从 '+precise(t)+' 开始 · 按 O 结束 · 再按 I 重新标记';return toast('起点已记下：'+precise(t));}if(action==='end'){if(markStart===null)return toast('先按 I 标记开始时间');if(t<=markStart)return toast('结束时间需要在起点之后');await api.control('pause',true);const recorded=await api.endRange();const cues=getCues().filter(c=>c.end>markStart&&c.start<t),shots=cues.length&&cues.length<=20?await busyWork(()=>api.captureCues(cues),'正在收集这段台词的画面…'):recorded?.shots?.length?recorded.shots:[await api.capture('subtitles')];noteDialog({itemId:current.id,episodeId:episode.id,kind:'quote',start:markStart,end:t,text:cues.map(c=>c.text).join('\n')||recorded?.shots?.map(s=>s.text).filter(Boolean).join('\n')||state['sub-text']||'',shots,color:'gold'});markStart=null;$('#mark-strip').hidden=true;return;}if(['quote','shot','frame'].includes(action)){const wasPaused=!!state.pause;await api.control('pause',true);const shot=await api.capture(action==='frame'?'video':'subtitles');if(action!=='quote'){await api.saveNote({itemId:current.id,episodeId:episode.id,kind:action,start:shot.time,end:shot.time,text:'',shots:[shot],color:'gold'});await api.control('pause',wasPaused);await refresh();panel='notes';$$('[data-panel]').forEach(b=>b.classList.toggle('active',b.dataset.panel==='notes'));renderPanel();toast(action==='frame'?'这一帧已收藏 · 可在摘记中编辑感想':'原尺寸截图已保存 · 可在摘记中导出');return;}let start=t,end=t,text=state['sub-text']||'';if(action==='quote'){const cue=getCues().find(c=>c.start<=t&&c.end>t);start=cue?.start??(Number.isFinite(state['sub-start'])?state['sub-start']:Math.max(0,t-3));end=cue?.end??(Number.isFinite(state['sub-end'])?state['sub-end']:Math.min(state.duration||t+3,t+3));if(end<=start)end=start+.1;text=state['sub-text']||cue?.text||'';if(!text.trim()){try{text=await api.recognizeSubtitle(shot.image);if(text)toast('已识别画面字幕，请核对原文');else toast('这帧未检测到可提取台词，可保留截图并手动填写');}catch{toast('未能识别画面字幕，可在摘记中填写原台词');}}}noteDialog({itemId:current.id,episodeId:episode.id,kind:action,start,end,text:action==='quote'?text:'',shots:[shot],color:'gold'});}}
function noteDialog(n){n=structuredClone(n);editingShots=n.shots||[];const range=n.kind==='quote';formDialog(n.id?'编辑摘记':range?'留住这段台词':n.kind==='frame'?'收藏这一帧':'保存截图',`<div class="two-col"><label>${range?'开始时间':'画面时间'}<input id="note-start" required value="${precise(n.start)}"></label><label ${range?'':'hidden'}>结束时间<input id="note-end" value="${precise(n.end)}"></label></div><small>支持 时:分:秒.毫秒，可微调到想要的瞬间。</small>${range?`<label style="margin-top:15px">台词<textarea id="note-text" placeholder="可手动填写或修正台词">${esc(n.text)}</textarea></label>`:''}<label style="margin-top:15px">我的感想<textarea id="note-comment" placeholder="这句话为什么打动你？这幅画面让你想到了什么？">${esc(n.comment)}</textarea></label><div class="two-col"><label>标签<input id="note-tags" value="${esc(n.tags)}" placeholder="例如：勇气、构图、人生"></label><label>标记颜色<select id="note-color">${[['gold','暖金'],['purple','淡紫'],['green','灰绿']].map(([v,t])=>`<option value="${v}" ${n.color===v?'selected':''}>${t}</option>`).join('')}</select></label></div><div class="row between"><small>附图 · 原尺寸保存</small>${range&&current?.id===n.itemId?'<button type="button" class="small" id="add-current-shot">＋ 加入当前画面</button>':''}</div><div class="shot-strip" id="note-shots"></div><small>保存后可回看片段、编辑或导出台词拼图。</small>`,async()=>{const start=parseTime($('#note-start').value),end=range?parseTime($('#note-end').value):start;await api.saveNote({...n,start,end,text:$('#note-text')?.value||'',comment:$('#note-comment').value,tags:$('#note-tags').value,color:$('#note-color').value,shots:editingShots});closeDialog();await refresh();if(view==='player')renderPanel();else renderNotesPage();toast('已留在你的摘记中')});const draw=()=>{$('#note-shots').innerHTML=editingShots.map((s,i)=>`<div class="shot-thumb"><img src="${imageUrl(s.image)}" alt="附图 ${i+1}"><button type="button" data-remove-shot="${i}" aria-label="移除附图">×</button><small>${precise(s.time)} · ${s.width}×${s.height}</small></div>`).join('');$$('[data-remove-shot]').forEach(b=>b.onclick=()=>{editingShots.splice(Number(b.dataset.removeShot),1);draw()});};draw();on('#add-current-shot',async()=>{if(editingShots.length>=20)return toast('每条摘记最多 20 张图');editingShots.push(await api.capture());draw()});}
function tracksDialog(){const tracks=state['track-list']||[];formDialog('字幕与音轨',`<label>字幕轨<select id="track-sub"><option value="no">关闭字幕</option>${tracks.filter(t=>t.type==='sub').map(t=>`<option value="${t.id}" ${t.selected?'selected':''}>${esc(t.title||t.lang||'字幕 '+t.id)}${t.external?'（外挂）':''}</option>`).join('')}</select></label><label>音轨<select id="track-audio">${tracks.filter(t=>t.type==='audio').map(t=>`<option value="${t.id}" ${t.selected?'selected':''}>${esc(t.title||t.lang||'音轨 '+t.id)}</option>`).join('')}</select></label><label>字幕延迟（秒；正值为延后）<input id="sub-delay" type="number" min="-120" max="120" step="0.1" value="${Number(state['sub-delay'])||0}"></label><button type="button" id="track-load">导入外挂字幕</button><p class="notice">软字幕可直接提取台词文本。画面里压制好的硬字幕会出现在截图中，台词文字可手动填写。</p>`,async()=>{await api.control('subtitle',$('#track-sub').value);if($('#track-audio').value)await api.control('audio',$('#track-audio').value);await api.control('subDelay',Number($('#sub-delay').value));await refresh();closeDialog();if(panel==='subtitles')renderPanel()});on('#track-load',async()=>{const r=await api.loadSubtitles(current.id,episode.id);if(r){await refresh();closeDialog();panel='subtitles';renderPanel();toast('字幕已导入')}});}
async function loadImage(src){return new Promise((resolve,reject)=>{const img=new Image;img.crossOrigin='anonymous';img.onload=()=>resolve(img);img.onerror=()=>reject(Error('图片无法读取'));img.src=src})}
async function collage(n){if(!n?.shots.length)return;dialog(`<h2>把这一刻，保存成图片</h2><div class="two-col"><label>拼图样式<select id="collage-mode"><option value="full">完整画面连续拼接 · 图二</option><option value="strip">首幅画面＋字幕条 · 图一</option></select></label><label>字幕条高度<select id="crop-ratio"><option value="0.18">底部 18%</option><option value="0.24" selected>底部 24%</option><option value="0.30">底部 30%</option><option value="0.40">底部 40%</option><option value="0.50">底部 50%</option></select></label></div><div class="row wrap"><label class="check"><input type="checkbox" id="collage-gap">画面间留细边</label><label class="check"><input type="checkbox" id="collage-caption">附上手写台词</label></div><small>每张图片按原始尺寸绘制，不缩小清晰度。字幕条模式保留第一张完整画面，可将其他画面设为新段落。</small><div class="shot-strip">${n.shots.map((s,i)=>`<label class="shot-thumb"><img src="${imageUrl(s.image)}" alt="第 ${i+1} 张"><span class="check"><input type="checkbox" data-full-shot="${i}" ${i===0?'checked disabled':''}>完整画面</span></label>`).join('')}</div><div class="collage-preview"><canvas id="collage"></canvas></div><div id="collage-info" class="notice"></div><div id="collage-error" class="error"></div><div class="buttons"><button id="cancel">关闭</button><button class="primary" id="save-collage">保存 PNG</button></div>`);let images;try{images=await Promise.all(n.shots.map(s=>loadImage(imageUrl(s.image))))}catch(e){$('#collage-error').textContent=e.message;return;}const draw=()=>{try{const mode=$('#collage-mode').value,ratio=Number($('#crop-ratio').value),gap=$('#collage-gap').checked?8:0,caption=$('#collage-caption').checked,width=Math.max(...images.map(i=>i.naturalWidth));const rows=images.map((img,i)=>{const full=mode==='full'||$(`[data-full-shot="${i}"]`).checked,h=full?img.naturalHeight:Math.round(img.naturalHeight*ratio);const lines=caption?(n.shots[i].text||n.text||'').split('\n'):[];const fontSize=Math.max(18,Math.round(width*.025));return {img,h,sy:img.naturalHeight-h,lines,fontSize,captionHeight:lines.length?(lines.length+1)*fontSize*1.45:0};});const height=Math.ceil(rows.reduce((s,r)=>s+r.h+r.captionHeight,0)+gap*(rows.length-1));if(height>32760||width*height>100000000)throw Error('这张长图超过安全画布尺寸，请把摘记拆成较短的几段后导出。原图不会缩小。');const canvas=$('#collage');canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');ctx.fillStyle='#08080a';ctx.fillRect(0,0,width,height);let y=0;for(const r of rows){ctx.drawImage(r.img,0,r.sy,r.img.naturalWidth,r.h,(width-r.img.naturalWidth)/2,y,r.img.naturalWidth,r.h);y+=r.h;if(r.lines.length){ctx.fillStyle='#eee9df';ctx.font=`${r.fontSize}px "Microsoft YaHei"`;ctx.textAlign='center';for(const line of r.lines){y+=r.fontSize*1.45;ctx.fillText(line,width/2,y,width-40)}y+=r.fontSize*1.45;}y+=gap;}$('#collage-info').textContent=`${width} × ${height} 像素 · PNG 无损图片 · ${images.length} 幅画面`;$('#collage-error').textContent='';$('#save-collage').disabled=false;}catch(e){$('#collage-error').textContent=e.message;$('#save-collage').disabled=true;}};$$('#modal select,#modal input').forEach(x=>x.onchange=draw);draw();on('#save-collage',async()=>{const out=await api.exportImage($('#collage').toDataURL('image/png'),(data.items.find(i=>i.id===n.itemId)?.title||'观影')+'-'+stamp(n.start).replaceAll(':','-'));if(out)toast('原尺寸图片已保存')});}
let autoNextPending=false;api.onState(s=>{state=s;if(view!=='player'||!$('#time'))return;const t=Number(s['time-pos'])||0,dur=Number(s.duration)||0;if(document.activeElement!==$('#seek')){$('#seek').max=dur||1;$('#seek').value=t;$('#time').textContent=stamp(t)+' / '+stamp(dur)}$('#play-toggle').textContent=s.pause?'▶':'Ⅱ';if(document.activeElement!==$('#volume'))$('#volume').value=s.volume??70;$('#speed').value=s.speed||1;$('#mute').textContent=s.mute?'静音':'♪';const p=s['video-params'];if(p)$('#quality').textContent=`${p.w} × ${p.h} · 原画${s['hwdec-current']&&s['hwdec-current']!=='no'?' · 硬件解码':''}`;$('#review-strip').hidden=s.reviewEnd===null||s.reviewEnd===undefined;$('#review-label').textContent=s.reviewLoop?'正在循环回味这段台词':'正在回看片段 · 到 '+stamp(s.reviewEnd)+' 暂停';renderMarks();if(s['eof-reached']&&data.settings.autoNext&&current?.kind==='series'&&!autoNextPending&&!s.reviewEnd){const index=current.episodes.findIndex(e=>e.id===episode.id),next=current.episodes[index+1];if(next){autoNextPending=true;safe(()=>openMovie(current.id,next.id)).finally(()=>autoNextPending=false);}}});api.onKey(a=>safe(()=>keyAction(a)));api.onError(toast);
document.addEventListener('keydown',e=>{if(view!=='player'||$('#modal').open||['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.target.isContentEditable||e.ctrlKey||e.altKey||e.metaKey)return;const card=e.target.closest('[data-note-id]');if(card){const selector={g:'[data-collage]',x:'[data-edit-note]',Delete:'[data-delete-note]',Enter:'[data-revisit]',u:'[data-loop]'}[e.key];if(selector){e.preventDefault();card.querySelector(selector)?.click();return;}}const keys={' ':'toggle','ArrowLeft':'back','ArrowRight':'forward','.':'nextFrame',',':'previousFrame'},action={h:'immersive',c:'controls',p:'panel','1':'notesPanel','2':'subtitlesPanel','3':'episodesPanel',t:'tracks',l:'loadSubs',e:'exportNotes',r:'exitReview',q:'backLibrary',a:'archive',v:'speed',d:'collectCues',ArrowUp:'volumeUp',ArrowDown:'volumeDown',F1:'help',i:'start',o:'end',s:'shot',b:'frame',n:'quote',f:'fullscreen',m:'mute',Escape:'escape'}[e.key.toLowerCase()]||{ArrowUp:'volumeUp',ArrowDown:'volumeDown',F1:'help',I:'start',O:'end',S:'shot',B:'frame',N:'quote',F:'fullscreen',M:'mute'}[e.key];if(action){e.preventDefault();safe(()=>keyAction(action));}else if(keys[e.key]){e.preventDefault();if(e.key===' '&&e.repeat)return;safe(()=>api.control(keys[e.key]==='back'||keys[e.key]==='forward'?'relative':keys[e.key],keys[e.key]==='back'?-5:5));}});
document.addEventListener('dragenter',e=>{if(![...(e.dataTransfer?.types||[])].includes('Files'))return;e.preventDefault();dragDepth++;document.body.classList.add('dragging-files')});
document.addEventListener('dragleave',e=>{e.preventDefault();dragDepth=Math.max(0,dragDepth-1);if(!dragDepth)document.body.classList.remove('dragging-files')});
document.addEventListener('dragover',e=>{e.preventDefault();if(e.dataTransfer)e.dataTransfer.dropEffect='copy'});
document.addEventListener('drop',e=>{e.preventDefault();dragDepth=0;document.body.classList.remove('dragging-files');const paths=[...e.dataTransfer.files].map(f=>api.filePath(f)).filter(Boolean);if(!paths.length)return;if(importState.running)return toast('正在保存上一批资源，请稍候');if($('#modal').open&&!$('#import-drop'))return toast('请先关闭当前编辑窗口，再拖入资源');if($('#import-drop'))safe(()=>startImport(paths));else importDialog(paths);});
safe(async()=>{await refresh();render()});
function removeMovieDialog(id){const i=data.items.find(x=>x.id===id);dialog(`<h2>移出片库</h2><p>移除「${esc(i.title)}」及其笔记和观影记录。</p><label class="check"><input type="checkbox" id="delete-media">同时将观影保存的视频副本移入回收站</label><p class="notice">保留的副本仍可在「全部资源」找到；原下载文件不会删除。共用副本会在最后一条引用移除后才删除。</p><div class="buttons"><button id="cancel">取消</button><button id="remove-confirm" class="danger">确认移除</button></div>`);on('#remove-confirm',async()=>{await api.removeItem(id,$('#delete-media').checked);closeDialog();await refresh();view='library';current=null;render()});}
async function renderResources(){const entries=await api.resources();if(view!=='resources'||!$('.main'))return;resourceRows=entries.map(e=>({...e,batchId:e.orphan?'orphan:'+e.path:'episode:'+e.id}));$('.main').innerHTML=`<div class="top"><div><h1>全部资源</h1><small>包括已入库影片和保留的视频副本。按住 Shift 可连续选择。</small></div><button id="vault-folder">打开保存文件夹</button></div><div id="resource-list" class="source-grid">${resourceRows.map((e,n)=>`<article class="source">${batchCheckbox('resources',e.batchId,'选择资源 '+e.title)}<h3>${esc(e.title)}</h3><p>${e.orphan?'保留副本 · 未加入片库':e.mediaFile?'影库已保存':!e.path?'已同步档案 · 视频待关联':'引用文件或网络链接'} · ${formatBytes(e.bytes||0)}</p><p class="details-path">${esc(e.path)}</p><div class="row">${e.orphan?`<button data-resource-add="${n}">重新加入片库</button><button class="danger" data-resource-trash="${n}">移入回收站</button>`:`<button data-resource-detail="${e.itemId}">影片档案</button>`}</div></article>`).join('')||'<p>还没有资源</p>'}</div>`;mountBatch('resources','#resource-list',resourceRows.map(e=>e.batchId));on('#vault-folder',()=>api.openStorage());$$('[data-resource-detail]').forEach(b=>b.onclick=()=>details(b.dataset.resourceDetail));$$('[data-resource-add]').forEach(b=>b.onclick=()=>safe(async()=>{await api.importPaths([resourceRows[Number(b.dataset.resourceAdd)].path]);await refresh();renderResources()}));$$('[data-resource-trash]').forEach(b=>b.onclick=()=>confirmDialog('移入回收站','将这份没有记录引用的视频副本移入回收站？',async()=>{await api.deleteResource(resourceRows[Number(b.dataset.resourceTrash)].path);await refresh();renderResources()}));}

function applyPlayerLayout(){const shell=$('.player-shell');if(!shell)return;shell.classList.toggle('focus-mode',focusMode);shell.classList.toggle('immersive',focusMode);shell.classList.toggle('controls-collapsed',controlsHidden);shell.classList.toggle('panel-collapsed',panelHidden);if($('#focus'))$('#focus').textContent=focusMode?'退出沉浸 H':'沉浸观看 H';if($('#toggle-controls'))$('#toggle-controls').textContent=controlsHidden?'展开操作栏 C':'收起操作栏 C';if($('#toggle-panel'))$('#toggle-panel').textContent=panelHidden?'展开摘记 P':'收起摘记 P';scheduleBounds();}
function shortcutHelp(){dialog(`<h2>观影快捷键</h2><p>双击视频：暂停 / 开始；单击不会打断播放。</p><div class="notice">空格 暂停 / 开始 · ← / → 前后 5 秒 · ↑ / ↓ 音量<br>N 摘一句 · S 截图 · B 收藏画面 · I / O 片段起止<br>, / . 上一帧 / 下一帧 · V 切换倍速 · M 静音<br>H 一键沉浸 / 恢复 · C 收起 / 展开操作栏 · P 收起 / 展开摘记栏<br>F 全屏 · Esc 退出沉浸并恢复面板<br>1 摘记 · 2 台词 · 3 选集 · D 摘录勾选台词<br>T 字幕 / 音轨 · L 导入字幕 · E 导出影片摘记<br>R 结束片段回看 · A 影片档案 · Q 返回片库 · F1 此说明</div><p>沉浸时把鼠标移到画面上沿，可暂时展开操作栏。编辑笔记时 Ctrl + Enter 保存，Esc 关闭，Alt + J 加入当前画面。选中摘记卡片时：Enter 回看、U 循环、G 导出图片、X 编辑、Delete 删除。</p><div class="buttons"><button id="cancel">关闭</button></div>`);}
document.addEventListener('keydown',e=>{if($('#modal').open&&e.altKey&&e.key.toLowerCase()==='j'&&$('#add-current-shot')){e.preventDefault();$('#add-current-shot').click();return;}if($('#modal').open&&e.ctrlKey&&e.key==='Enter'&&$('#dialog-form')){e.preventDefault();$('#dialog-form').requestSubmit();}});


